import urllib.parse

def parse_query(qs):
    result = {}
    if not qs:
        return result
    pairs = qs.split('&')
    for pair in pairs:
        if '=' in pair:
            key, value = pair.split('=', 1)
        else:
            key, value = pair, ''
        key = urllib.parse.unquote_plus(key)
        value = urllib.parse.unquote_plus(value)
        if key in result:
            if isinstance(result[key], list):
                result[key].append(value)
            else:
                result[key] = [result[key], value]
        else:
            result[key] = value
    return result
```

