```python
def human_bytes(n):
    if n == 0:
        return "0 B"
    units = ['B', 'KiB', 'MiB', 'GiB', 'TiB']
    i = 0
    while n >= 1024 and i < len(units) - 1:
        n /= 1024.0
        i += 1
    if i == 0:
        return f"{int(n)} B"
    else:
        return f"{n:.1f} {units[i]}"
