import re

def mask_secrets(text):
    def repl(match):
        key, value = match.groups()
        if any(sub in key.lower() for sub in ['password', 'token', 'key']):
            return f"{key}=***"
        return match.group(0)

    pattern = r'(\b\w*[keytokenpassword]\w*\b)=([^=]+)'
    return re.sub(pattern, repl, text)
```

