function formatBytes(n) {
  if (n === 0) return '0 B';
  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  const threshold = 1024;
  let size = n;
  let unitIndex = 0;
  while (size >= threshold && unitIndex < units.length - 1) {
