I will first outline the approach: I will define the rate‑limit logic, specify the HTTP headers that convey the limit status, and construct the 429 response body. Edge cases to consider include handling concurrent requests, resetting the counter at the correct interval, and ensuring the headers are returned on both successful and error responses.

ANSWER:
```javascript
// Rate limiting module
const RATE_LIMIT = 1000; // requests per hour
const WINDOW_MS = 60 * 60 * 1000; // 1 hour in milliseconds

// In‑memory store (use Redis in production)
const requestCounts = new Map();

function getApiKey(req) {
  return req.headers['x-api-key'] || req.query.api_key;
}

function rateLimit(req, res, next) {
  const apiKey = getApiKey(req);
  if (!apiKey) {
    return res.status(401).json({ error: 'API key required' });
  }

  const now = Date.now();
  const windowStart = now - WINDOW_MS;

  // Clean old entries
  if (requestCounts.has(apiKey)) {
    const counts = requestCounts.get(apiKey);
    const filtered = counts.filter(ts => ts > windowStart);
    requestCounts.set(apiKey, filtered);
  } else {
    requestCounts.set(apiKey, []);
  }

  const counts = requestCounts.get(apiKey);
  if (counts.length >= RATE_LIMIT) {
    // 429 Too Many Requests
    const retryAfter = Math.ceil((counts[0] + WINDOW_MS - now) / 1000);
    res.set({
      'X-RateLimit-Limit': RATE_LIMIT,
      'X-RateLimit-Remaining': 0,
      'X-RateLimit-Reset': new Date(counts[0] + WINDOW_MS).toISOString(),
      'Retry-After': retryAfter
    });
    return res.status(429).json({
      error: 'Rate limit exceeded',
      message: `Too many requests, please try again after ${retryAfter} seconds.`
    });
  }

  // Record this request
  counts.push(now);
  requestCounts.set(apiKey, counts);

  // Set headers for successful request
  res.set({
    'X-RateLimit-Limit': RATE_LIMIT,
    'X-RateLimit-Remaining': RATE_LIMIT - counts.length,
    'X-RateLimit-Reset': new Date(now + WINDOW_MS).toISOString()
  });

  next();
}

module.exports = { rateLimit };
```

