I'll create a React Native FlatList component that implements infinite scroll. The approach involves using the onEndReached callback to detect when the user has scrolled near the end of the list, triggering a loadMore function to fetch additional data. I'll also implement onEndReachedThreshold to control when the callback fires, and include proper state management for loading indicators and pagination.

export default function InfiniteScrollList() {
  const [data, setData] = useState([]);
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(false);
  const [hasMore, setHasMore] = useState(true);

  const loadMore = useCallback(() => {
    if (loading || !hasMore) return;

    setLoading(true);
    // Simulate API call
    setTimeout(() => {
      const newData = Array.from({ length: 20 }, (_, i) => ({
        id: `${page}-${i}`,
        title: `Item ${page}-${i}`,
      }));

      setData(prev => [...prev, ...newData]);
      setPage(prev => prev + 1);
      setLoading(false);

      // Stop loading after 5 pages for demo
      if (page >= 5) setHasMore(false);
    }, 1000);
  }, [loading, hasMore, page]);

  const renderItem = ({ item }) => (
    <View style={{ padding: 20, borderBottomWidth: 1, borderColor: '#eee' }}>
      <Text>{item.title}</Text>
    </View>
  );

  return (
    <FlatList
      data={data}
      renderItem={renderItem}
      keyExtractor={item => item.id}
      onEndReached={loadMore}
      onEndReachedThreshold={0.5}
      ListFooterComponent={loading ? <ActivityIndicator style={{ marginVertical: 20 }} /> : null}
    />
  );
}

