rn-041.text:
I'll create a custom React Native hook that fetches data when the component mounts and properly cancels the request when the component unmounts. The hook will use AbortController to handle cancellation, which is the modern way to cancel fetch requests in JavaScript. I'll also handle edge cases like network errors and ensure the cleanup function is called to prevent memory leaks.

ANSWER:
```javascript
import { useState, useEffect } from 'react';

export const useFetch = (url) => {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const controller = new AbortController();
    const signal = controller.signal;

    const fetchData = async () => {
      try {
        const response = await fetch(url, { signal });
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const result = await response.json();
        setData(result);
      } catch (err) {
        if (err.name === 'AbortError') {
          // Request was cancelled, which is expected during cleanup
          console.log('Fetch aborted');
        } else {
          setError(err.message);
        }
      } finally {
        setLoading(false);
      }
    };

    fetchData();

    // Cleanup function to cancel the request when component unmounts
    return () => {
      controller.abort();
    };
  }, [url]);

  return { data, loading, error };
};
```

